import{_ as s,o as a,c as i,a2 as r}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"Pausing groups","description":"","frontmatter":{},"headers":[],"relativePath":"bullmq-pro/groups/pausing-groups.md","filePath":"bullmq-pro/groups/pausing-groups.md","lastUpdated":1755971998000}'),t={name:"bullmq-pro/groups/pausing-groups.md"};function o(p,e,l,u,n,d){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="pausing-groups" tabindex="-1">Pausing groups <a class="header-anchor" href="#pausing-groups" aria-label="Permalink to &quot;Pausing groups&quot;">​</a></h1><p>BullMQ Pro supports pausing groups globally. A group is paused when no workers will pick up any jobs that belongs to the paused group. When you pause a group, the workers that are currently busy processing a job from that group, will continue working on that job until it completes (or failed), and then will just keep idling until the group has been resumed.</p><p>Pausing a group is performed by calling the <code>pauseGroup</code> method on a <a href="https://api.bullmq.pro/classes/v7.QueuePro.html#pausegroup" target="_blank" rel="noreferrer"><code>Queue</code></a> instance:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> myQueue.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pauseGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;groupId&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Even if the <code>groupId</code> does not exist at that time, the <code>groupId</code> will be added in our paused list as a group could be ephemeral</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>pauseGroup</code> will return <code>false</code> if the group is already paused.</p></div><p>Resuming a group is performed by calling the <code>resumeGroup</code> method on a <a href="https://api.bullmq.pro/classes/v7.QueuePro.html#resumegroup" target="_blank" rel="noreferrer"><code>Queue</code></a> instance:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> myQueue.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">resumeGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;groupId&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><code>resumeGroup</code> will return <code>false</code> if the group does not exist or when the group is already resumed.</p></div><h2 id="read-more" tabindex="-1">Read more: <a class="header-anchor" href="#read-more" aria-label="Permalink to &quot;Read more:&quot;">​</a></h2><ul><li>💡 <a href="https://api.bullmq.pro/classes/v7.QueuePro.html#pausegroup" target="_blank" rel="noreferrer">Pause Group API Reference</a></li><li>💡 <a href="https://api.bullmq.pro/classes/v7.QueuePro.html#resumegroup" target="_blank" rel="noreferrer">Resume Group API Reference</a></li></ul>',11)])])}const g=s(t,[["render",o]]);export{c as __pageData,g as default};
